def gin(routes):
 imports='"github.com/gin-gonic/gin"\n"net/http"'
 if 'strconv.' in routes: imports+='\n"strconv"'
 return 'package main\nimport (\n'+imports+'\n)\nfunc main() {\nr := gin.New()\nr.Use(gin.Recovery())\n'+routes+'\nr.Run("127.0.0.1:3000")\n}\n'
def fiber(routes): return 'package main\nimport "github.com/gofiber/fiber/v2"\nfunc main() {\napp := fiber.New()\n'+routes+'\napp.Listen("127.0.0.1:3000")\n}\n'
def phoenix(routes, actions): return '# lib/school_web/router.ex\ndefmodule SchoolWeb.Router do\n use SchoolWeb, :router\n pipeline :api do\n  plug :accepts, ["json"]\n end\n scope "/", SchoolWeb do\n  pipe_through :api\n'+routes+'\n end\nend\n\n# lib/school_web/controllers/lesson_controller.ex\ndefmodule SchoolWeb.LessonController do\n use SchoolWeb, :controller\n'+actions+'\nend\n'
course('gin','Gin','go','Examples use Gin 1.10 with Go 1.22 or later.','Create a practice folder, run go mod init school and go get github.com/gin-gonic/gin@v1.10.0. Save one example as main.go and run go run . Use http://127.0.0.1:3000.','Gin is a Go web framework. Its context object helps read request data and write replies.',[
L('first-route','Send a text reply','GET /hello calls this handler. Context.String sends formatted text with a status.',gin('r.GET("/hello", func(c *gin.Context) { c.String(http.StatusOK, "Hello, Asha!") })'),'Hello, Asha!','Change the greeting.','Use a matching HTTP method and path.'),
L('json','Send a JSON object','gin.H is a short map type for named data. Open GET /book.',gin('r.GET("/book", func(c *gin.Context) { c.JSON(http.StatusOK, gin.H{"title": "Moon Trip"}) })'),'{"title":"Moon Trip"}','Add a pages field.','Use c.JSON so the response has the right content type.'),
L('path-inputs','Read a path parameter','A colon marks a route value. GET /hello/Ravi puts Ravi in the name parameter.',gin('r.GET("/hello/:name", func(c *gin.Context) { c.String(http.StatusOK, "Hi, %s!", c.Param("name")) })'),'Hi, Ravi!','Visit /hello/Asha.','A route value is text until it is parsed and checked.'),
L('query','Read a query value','DefaultQuery reads a query parameter and supplies a fallback. GET /page uses the text fallback 1.',gin('r.GET("/page", func(c *gin.Context) { c.JSON(http.StatusOK, gin.H{"page": c.DefaultQuery("n", "1")}) })'),'{"page":"1"}','Visit /page?n=3.','Query values are strings, even when they look like numbers.'),
L('number-checks','Parse a number','strconv.Atoi turns text into an int or reports an error. Open GET /double/4.',gin('r.GET("/double/:n", func(c *gin.Context) {\n n, err := strconv.Atoi(c.Param("n"))\n if err != nil { c.String(http.StatusBadRequest, "Use a whole number"); return }\n c.JSON(http.StatusOK, gin.H{"answer": n * 2})\n})'),'{"answer":8}','Try /double/cat.','Always check the parse error before using the number.'),
L('json-body','Read a JSON body','ShouldBindJSON reads and checks JSON fields. Send POST /books with application/json and {"title":"Moon Trip"}.',gin('type Book struct { Title string `json:"title" binding:"required"` }\nr.POST("/books", func(c *gin.Context) {\n var book Book\n if err := c.ShouldBindJSON(&book); err != nil { c.JSON(http.StatusBadRequest, gin.H{"error": "Title needed"}); return }\n c.JSON(http.StatusCreated, book)\n})'),'{"title":"Moon Trip"}','Send an empty object.','Pass a pointer so the binder can fill the struct.'),
L('groups','Share a route prefix','A group gives related handlers a common path prefix. Open GET /api/books.',gin('api := r.Group("/api")\napi.GET("/books", func(c *gin.Context) { c.JSON(http.StatusOK, []string{"Moon Trip"}) })'),'["Moon Trip"]','Add another route inside api.','The group prefix belongs in the requested URL.'),
L('middleware','Run a shared request step','Middleware can set request values before calling the next handler. Open GET /school.',gin('r.Use(func(c *gin.Context) { c.Set("school", "Oak School"); c.Next() })\nr.GET("/school", func(c *gin.Context) { c.String(http.StatusOK, c.GetString("school")) })'),'Oak School','Change the stored school name.','Request context values belong to the current request.'),
L('headers','Add response metadata','Header sets a response header. Open GET /note and inspect Cache-Control.',gin('r.GET("/note", func(c *gin.Context) { c.Header("Cache-Control", "no-store"); c.String(http.StatusOK, "Practice note") })'),'Practice note','Use curl -i to see the header.','Set headers before writing the response body.'),
L('redirects','Return a redirect','Redirect asks the client to visit a new URL. GET /start ends at /hello in a browser.',gin('r.GET("/start", func(c *gin.Context) { c.Redirect(http.StatusFound, "/hello") })\nr.GET("/hello", func(c *gin.Context) { c.String(http.StatusOK, "Welcome") })'),'Welcome','Inspect the initial 302 response.','A redirect is a second client request.'),
L('not-found','Handle unmatched routes','NoRoute supplies a fallback handler. GET /missing has no normal route.',gin('r.NoRoute(func(c *gin.Context) { c.JSON(http.StatusNotFound, gin.H{"error": "Page not found"}) })'),'{"error":"Page not found"}','Try another unknown path.','Keep the 404 status even with a friendly body.'),
L('abort','Stop a handler chain','AbortWithStatusJSON stops later handlers in the chain. GET /closed receives this practice block message.',gin('r.GET("/closed", func(c *gin.Context) { c.AbortWithStatusJSON(http.StatusForbidden, gin.H{"error": "Closed for practice"}) }, func(c *gin.Context) { c.String(http.StatusOK, "This is skipped") })'),'{"error":"Closed for practice"}','Replace the blocking first handler with c.Next and compare.','Abort stops later handlers but does not return from the current Go function.')])
course('fiber','Fiber','go','Examples target Fiber v2, specifically v2.52, and Go 1.22 or later. Fiber v3 has different APIs.','Run go mod init school and go get github.com/gofiber/fiber/v2@v2.52.5 in a practice folder. Save one example as main.go and run go run . Use http://127.0.0.1:3000.','Fiber is a Go web framework with a compact request context. These lessons use its stable v2 API.',[
L('first-route','Send a greeting','A Fiber handler returns an error value. SendString writes the response text. Open GET /hello.',fiber('app.Get("/hello", func(c *fiber.Ctx) error { return c.SendString("Hello, Asha!") })'),'Hello, Asha!','Change the greeting.','Return the error from response-writing methods.'),
L('json','Send named data','JSON writes an object as JSON. Open GET /book.',fiber('app.Get("/book", func(c *fiber.Ctx) error { return c.JSON(fiber.Map{"title": "Moon Trip"}) })'),'{"title":"Moon Trip"}','Add a pages field.','Use the Fiber v2 context pointer shown in this course.'),
L('path-inputs','Read a route value','Params reads a named path part. Open GET /hello/Ravi.',fiber('app.Get("/hello/:name", func(c *fiber.Ctx) error { return c.SendString("Hi, " + c.Params("name") + "!") })'),'Hi, Ravi!','Visit /hello/Asha.','Path parameters start as text.'),
L('query','Read a query string','Query reads a query value and can take a default. Open GET /page.',fiber('app.Get("/page", func(c *fiber.Ctx) error { return c.JSON(fiber.Map{"page": c.Query("n", "1")}) })'),'{"page":"1"}','Visit /page?n=3.','A query value remains text until you parse it.'),
L('typed-params','Parse an integer input','ParamsInt parses a route value as an integer. Open GET /double/4.',fiber('app.Get("/double/:n", func(c *fiber.Ctx) error { n, err := c.ParamsInt("n"); if err != nil { return c.Status(400).SendString("Use a whole number") }; return c.JSON(fiber.Map{"answer": n * 2}) })'),'{"answer":8}','Try /double/cat.','Check the error before using the parsed number.'),
L('json-body','Read a body into a struct','BodyParser fills a struct from the request body. Send POST /books with application/json and {"title":"Moon Trip"}.',fiber('type Book struct { Title string `json:"title"` }\napp.Post("/books", func(c *fiber.Ctx) error { var book Book; if err := c.BodyParser(&book); err != nil || book.Title == "" { return c.Status(400).JSON(fiber.Map{"error": "Title needed"}) }; return c.Status(201).JSON(book) })'),'{"title":"Moon Trip"}','Send an empty object.','Parsing does not replace checks for a useful field value.'),
L('groups','Group routes','Group adds a shared path prefix. Open GET /api/books.',fiber('api := app.Group("/api")\napi.Get("/books", func(c *fiber.Ctx) error { return c.JSON([]string{"Moon Trip"}) })'),'["Moon Trip"]','Add a /pets route to the group.','Request the group prefix as well as the inner path.'),
L('locals','Share request data','Locals stores a value for the current request. A middleware can set it before a route reads it.',fiber('app.Use(func(c *fiber.Ctx) error { c.Locals("school", "Oak School"); return c.Next() })\napp.Get("/school", func(c *fiber.Ctx) error { return c.SendString(c.Locals("school").(string)) })'),'Oak School','Change the school name.','Check a value type if it may come from a different source.'),
L('headers','Set a reply header','Set adds a response header. Open GET /note and inspect Cache-Control.',fiber('app.Get("/note", func(c *fiber.Ctx) error { c.Set("Cache-Control", "no-store"); return c.SendString("Practice note") })'),'Practice note','Inspect the response with curl -i.','Set headers before sending the body.'),
L('redirects','Point to another route','Redirect sends a location and status. A browser following GET /start reaches /hello.',fiber('app.Get("/start", func(c *fiber.Ctx) error { return c.Redirect("/hello", 302) })\napp.Get("/hello", func(c *fiber.Ctx) error { return c.SendString("Welcome") })'),'Welcome','Inspect the first 302 response.','A redirect requires another client request.'),
L('status','Reply with a missing-item status','Status selects a code before a body is sent. Open GET /missing.',fiber('app.Get("/missing", func(c *fiber.Ctx) error { return c.Status(404).JSON(fiber.Map{"error": "Book not found"}) })'),'{"error":"Book not found"}','Inspect the status too.','A helpful error body should keep the correct error status.'),
L('fallback','Handle an unknown URL','A final Use handler can reply when no earlier route handled the request. Open GET /unknown.',fiber('app.Get("/", func(c *fiber.Ctx) error { return c.SendString("Home") })\napp.Use(func(c *fiber.Ctx) error { return c.Status(404).SendString("Page not found") })'),'Page not found','Visit / to compare.','Put a catch-all handler after the real routes.')])
course('phoenix','Phoenix','elixir','Examples use Phoenix 1.7 with Elixir 1.14 or later.','Create an app named school with mix phx.new school --no-ecto --no-html --no-assets. Enter school and run mix deps.get. Put each labelled section in its named file, then run mix phx.server. Use http://127.0.0.1:4000.','Phoenix is an Elixir web framework. It uses a router, controllers and a connection value to handle requests.',[
L('first-route','Make a controller reply','The router maps GET /hello to a controller action. text sends a plain response.',phoenix('get "/hello", LessonController, :hello','def hello(conn, _params), do: text(conn, "Hello, Asha!")'),'Hello, Asha!','Change the greeting.','The SchoolWeb module prefix must match the app name school.'),
L('json','Send JSON data','json turns an Elixir map into a JSON reply. Open GET /book.',phoenix('get "/book", LessonController, :book','def book(conn, _params), do: json(conn, %{title: "Moon Trip"})'),'{"title":"Moon Trip"}','Add a page count.','A map holds named data; its field order is not important.'),
L('path-inputs','Read a path value','A colon marks a router input. Pattern matching reads its string-keyed parameter. Open GET /hello/Ravi.',phoenix('get "/hello/:name", LessonController, :hello','def hello(conn, %{"name" => name}), do: text(conn, "Hi, #{name}!")'),'Hi, Ravi!','Visit /hello/Asha.','HTTP parameter keys are strings, not atoms.'),
L('query','Read query data','The params map includes query values. Open GET /search?q=cat.',phoenix('get "/search", LessonController, :search','def search(conn, params), do: json(conn, %{term: Map.get(params, "q", "")})'),'{"term":"cat"}','Leave out q.','Query values are untrusted text.'),
L('parse-number','Check a path number','Integer.parse reads a number and the unused text. Open GET /double/4.',phoenix('get "/double/:n", LessonController, :twice','def twice(conn, %{"n" => raw}) do\n case Integer.parse(raw) do\n  {n, ""} -> json(conn, %{answer: n * 2})\n  _ -> conn |> put_status(400) |> json(%{error: "Use a whole number"})\n end\nend'),'{"answer":8}','Visit /double/4cats.','Check that no trailing text remains after the parsed number.'),
L('post-body','Read JSON parameters','Send POST /books with application/json and {"title":"Moon Trip"}. The endpoint parser puts the fields into params.',phoenix('post "/books", LessonController, :create','def create(conn, %{"title" => title}) when is_binary(title), do: conn |> put_status(201) |> json(%{title: title})\ndef create(conn, _params), do: conn |> put_status(400) |> json(%{error: "Title needed"})'),'{"title":"Moon Trip"}','Send an empty object.','Provide a fallback function clause for input that does not match.'),
L('status','Report a missing item','put_status returns an updated connection. Pass that value to json. Open GET /missing.',phoenix('get "/missing", LessonController, :missing','def missing(conn, _params), do: conn |> put_status(404) |> json(%{error: "Book not found"})'),'{"error":"Book not found"}','Inspect the 404 status.','Connection functions return a new value; keep using that returned value.'),
L('headers','Set response metadata','put_resp_header adds a header to the connection. Open GET /note.',phoenix('get "/note", LessonController, :note','def note(conn, _params), do: conn |> put_resp_header("cache-control", "no-store") |> text("Practice note")'),'Practice note','Inspect the cache header.','Use lower-case header names with Plug.'),
L('redirects','Return a redirect','redirect sends a location. A browser following GET /start reaches /hello.',phoenix('get "/start", LessonController, :start\nget "/hello", LessonController, :hello','def start(conn, _params), do: redirect(conn, to: "/hello")\ndef hello(conn, _params), do: text(conn, "Welcome")'),'Welcome','Inspect the initial 302 response.','Use an internal path for this example, not an unchecked outside destination.'),
L('lists','Return a JSON list','A map can wrap a list under a clear key. Open GET /books.',phoenix('get "/books", LessonController, :books','def books(conn, _params), do: json(conn, %{books: ["Moon Trip", "Sun Trip"]})'),'{"books":["Moon Trip","Sun Trip"]}','Add a third title.','Keep the response shape consistent for clients.'),
L('halt','Stop later processing','halt marks the connection so later plugs stop. Open GET /closed.',phoenix('get "/closed", LessonController, :closed','def closed(conn, _params), do: conn |> send_resp(403, "Closed for practice") |> halt()'),'Closed for practice','Change the public message.','halt does not itself send a response; send it first.'),
L('empty-response','Return no content','send_resp can send an empty body with status 204. Send DELETE /books/1.',phoenix('delete "/books/:id", LessonController, :remove','def remove(conn, _params), do: send_resp(conn, 204, "")'),'204 No Content; empty body','Inspect the reply in an HTTP client.','This practice action has no database record to remove.')])
